  const el = document.querySelector('[aria-label="Incident report content"]') || document.activeElement;
  const region = document.querySelector('[aria-label="Document editor"]') || document.querySelector('section');
  function describe(node) {
    if (!node) return null;
    return {
      tag: node.tagName,
      contentEditable: node.contentEditable,
      role: node.getAttribute && node.getAttribute('role'),
      className: node.className,
    };
  }
  // find element with aria-label Incident report content
  const candidates = Array.from(document.querySelectorAll('*')).filter(n => n.getAttribute && n.getAttribute('aria-label') === 'Incident report content');
  return candidates.map(describe);
}

