  const chain = [];
  while (node) {
    chain.push({tag: node.tagName, contentEditable: node.contentEditable, isContentEditable: node.isContentEditable, className: node.className});
    node = node.parentElement;
    if (chain.length > 8) break;
  }
  return chain;
}

